mapper.update:
update ${table}
set status = #{e.status},
    retry_count = #{e.retryCount},
    next_retry_time = #{e.nextRetryTime},
    api_log_id = #{e.apiLogId},
    reason = #{e.reason},
    task_id = #{e.taskId},
    modedatamodifydatetime = #{e.modedatamodifydatetime}
where id = #{e.id}

mapper.select:
select count(1) from ${table}
where type = 2 and dedup_key = #{dedupKey}
  and (modedatacreatedate > #{sinceDate}
       or (modedatacreatedate = #{sinceDate} and modedatacreatetime >= #{sinceTime}))
  and status in (0, 1)

select top ${limit} 
from ${table} m
where m.type = 2
  and m.status = 2
  and m.retry_count < #{maxRetry}
  and m.next_retry_time is not null
  and m.next_retry_time <= #{now}
order by m.id

mapper.delete:
delete from ${table}
where type = 2 and modedatacreatedate < #{beforeDate}
   or (modedatacreatedate = #{beforeDate} and modedatacreatetime < #{beforeTime})
